//! tonic gRPC handler for catalog (Go `handler/grpc.go`
//! parity, port-spec §5.1a). Maps proto payloads to/from the feature's
//! contract types and calls the usecase service — never mapping
//! from domain entities.
//!
//! The proto module is generated by `build.rs` into `OUT_DIR`; with package
//! `catalog.v1` and no `rust_package` override, `tonic::include_proto!` emits
//! a module named after the package with dots replaced by underscores:
//! `catalog_v1`.

use std::sync::Arc;

use tonic::{Request, Response, Status};

use crate::features::catalog::contract::{
    CreateProductRequest, ListProductsRequest, ProductResponse,
};
use crate::features::catalog::usecase::Service;
use crate::platform::errors::AppError;
use crate::platform::server::GRPC_MESSAGE_SIZE_LIMIT;

// The generated `CatalogService` trait carries `#[async_trait]`, whose boxed
// futures trip `clippy::double_must_use`; the attribute lives in `OUT_DIR` and
// cannot be fixed at source, so allow it for the whole generated module.
#[allow(clippy::double_must_use)]
pub mod catalog_v1 {
    tonic::include_proto!("catalog.v1");
}

use catalog_v1::{
    CreateProductRequest as PbCreateProductRequest, GetProductRequest,
    ListProductsRequest as PbListProductsRequest, ListProductsResponse as PbListProductsResponse,
    Product as PbProduct,
    catalog_service_server::{CatalogService, CatalogServiceServer},
};

/// tonic server implementation for the catalog feature. Generic over the
/// inbound port so tests inject a `MockService` and `di` wires
/// `Arc<dyn Service>`.
pub struct GrpcServer<S: Service + ?Sized> {
    service: Arc<S>,
}

// Manual `Clone` impl: `Arc<S>` is `Clone` for any `S`, including `?Sized`.
impl<S: Service + ?Sized> Clone for GrpcServer<S> {
    fn clone(&self) -> Self {
        Self {
            service: self.service.clone(),
        }
    }
}

impl<S: Service + ?Sized> GrpcServer<S> {
    pub fn new(service: Arc<S>) -> Self {
        Self { service }
    }
}

#[tonic::async_trait]
impl<S: Service + ?Sized + 'static> CatalogService for GrpcServer<S> {
    async fn create_product(
        &self,
        request: Request<PbCreateProductRequest>,
    ) -> Result<Response<PbProduct>, Status> {
        let req = request.into_inner();
        let response = self
            .service
            .create(CreateProductRequest {
                name: req.name,
                price_cents: req.price_cents,
                stock: req.stock,
            })
            .await
            .map_err(|e| AppError::from(e).to_grpc_status())?;
        Ok(Response::new(contract_to_pb(&response)))
    }

    async fn get_product(
        &self,
        request: Request<GetProductRequest>,
    ) -> Result<Response<PbProduct>, Status> {
        let id = request.into_inner().id;
        let response = self
            .service
            .get(id)
            .await
            .map_err(|e| AppError::from(e).to_grpc_status())?;
        Ok(Response::new(contract_to_pb(&response)))
    }

    async fn list_products(
        &self,
        request: Request<PbListProductsRequest>,
    ) -> Result<Response<PbListProductsResponse>, Status> {
        let req = request.into_inner();
        let response = self
            .service
            .list(ListProductsRequest {
                limit: Some(req.limit),
                offset: Some(req.offset),
            })
            .await
            .map_err(|e| AppError::from(e).to_grpc_status())?;
        Ok(Response::new(PbListProductsResponse {
            products: response.products.iter().map(contract_to_pb).collect(),
        }))
    }
}

/// Build the tonic service for `srv` with the feature's message-size caps.
pub fn server<S: Service + ?Sized + 'static>(
    srv: GrpcServer<S>,
) -> CatalogServiceServer<GrpcServer<S>> {
    CatalogServiceServer::new(srv)
        .max_decoding_message_size(GRPC_MESSAGE_SIZE_LIMIT)
        .max_encoding_message_size(GRPC_MESSAGE_SIZE_LIMIT)
}

fn contract_to_pb(resp: &ProductResponse) -> PbProduct {
    PbProduct {
        id: resp.id.clone(),
        name: resp.name.clone(),
        price_cents: resp.price_cents,
        stock: resp.stock,
        created_at: resp.created_at.clone(),
        updated_at: resp.updated_at.clone(),
    }
}

